-- Hand-written data step: each piece of content becomes one text per locale, JSON text in the column it held. A page's own text is its page language's; a component's, an incident's and a maintenance window's the install language's, Arabic when none is stored.
UPDATE "components" SET "name" = json_build_object(CASE WHEN (SELECT "value" FROM "settings" WHERE "key" = 'install_language') = '"en"' THEN 'en' ELSE 'ar' END, "name")::text, "description" = CASE WHEN "description" IS NULL THEN NULL ELSE json_build_object(CASE WHEN (SELECT "value" FROM "settings" WHERE "key" = 'install_language') = '"en"' THEN 'en' ELSE 'ar' END, "description")::text END;--> statement-breakpoint
UPDATE "incidents" SET "title" = json_build_object(CASE WHEN (SELECT "value" FROM "settings" WHERE "key" = 'install_language') = '"en"' THEN 'en' ELSE 'ar' END, "title")::text;--> statement-breakpoint
UPDATE "incident_updates" SET "message" = json_build_object(CASE WHEN (SELECT "value" FROM "settings" WHERE "key" = 'install_language') = '"en"' THEN 'en' ELSE 'ar' END, "message")::text;--> statement-breakpoint
UPDATE "maintenance_windows" SET "title" = json_build_object(CASE WHEN (SELECT "value" FROM "settings" WHERE "key" = 'install_language') = '"en"' THEN 'en' ELSE 'ar' END, "title")::text, "message" = json_build_object(CASE WHEN (SELECT "value" FROM "settings" WHERE "key" = 'install_language') = '"en"' THEN 'en' ELSE 'ar' END, "message")::text;--> statement-breakpoint
UPDATE "component_groups" SET "name" = json_build_object((SELECT "locale" FROM "status_pages" WHERE "status_pages"."id" = "component_groups"."page_id"), "name")::text;--> statement-breakpoint
UPDATE "status_pages" SET "title" = json_build_object("locale", "title")::text;--> statement-breakpoint
UPDATE "status_pages" SET "customization" = jsonb_set("customization"::jsonb, '{description}', jsonb_build_object("locale", "customization"::jsonb ->> 'description'))::text WHERE jsonb_typeof("customization"::jsonb -> 'description') = 'string';--> statement-breakpoint
UPDATE "status_pages" SET "customization" = jsonb_set("customization"::jsonb, '{labels}', (SELECT COALESCE(jsonb_object_agg("key", jsonb_build_object("status_pages"."locale", "value")), '{}'::jsonb) FROM jsonb_each_text("status_pages"."customization"::jsonb -> 'labels')))::text WHERE jsonb_typeof("customization"::jsonb -> 'labels') = 'object';--> statement-breakpoint
UPDATE "status_pages" SET "customization" = jsonb_set("customization"::jsonb, '{footerLinks}', (SELECT COALESCE(jsonb_agg(jsonb_set("link", '{label}', jsonb_build_object("status_pages"."locale", "link" ->> 'label')) ORDER BY "place"), '[]'::jsonb) FROM jsonb_array_elements("status_pages"."customization"::jsonb -> 'footerLinks') WITH ORDINALITY AS "links"("link", "place")))::text WHERE jsonb_typeof("customization"::jsonb -> 'footerLinks') = 'array';
